<template>

  <canvas ref="screenCanvas">Canvas not supported {{ refreshCanvas(text) }}</canvas>

</template>

<script>
export default {
  props: ["canvasWidth", "canvasHeight", "text", "textAlign", "backgroundColor", "frameImgUrl", "screenBlobImg"],
  data() {
    return {
    }
  },
  methods: {
    refreshCanvas(data) {
      // 自定义字体 https://www.zhihu.com/question/496036108
      const width = this.canvasWidth; const height = this.canvasHeight;

      const canvas = this.$refs.screenCanvas;
      if (canvas == null) return
      canvas.setAttribute("width", width + "")
      canvas.setAttribute("height", height + "")

      // canvas.style.width = this.canvasWidth / 4.5  + "px";
      // canvas.style.height = this.canvasHeight / 4.5  + "px";

      // 不支持canvas
      if (!canvas.getContext) return

      const ctx2d = canvas.getContext('2d');
      // 绘制背景颜色
      ctx2d.fillStyle = this.backgroundColor
      ctx2d.fillRect(0,0, width, height);

      // 选中的手机边框
      const phoneFrame = {
        path: this.frameImgUrl,
        x: width * 0.05, // 外壳起点
        y: height * 0.195,
        width: 1564,
        height: 3320,
        startX: 59.4, // 内容起点
        startY: 191.2,
        endX: 1501.4, // 内容终点
        endY: 3232.9,
        extraY: 1548.8 // 关机按键
      }

      const phoneFrameToPrevScale = width * 0.9 / phoneFrame.width
      phoneFrame.width = phoneFrame.width *  phoneFrameToPrevScale
      phoneFrame.height = phoneFrame.height *  phoneFrameToPrevScale
      phoneFrame.startX = phoneFrame.x + phoneFrame.startX *  phoneFrameToPrevScale
      phoneFrame.startY = phoneFrame.y + phoneFrame.startY *  phoneFrameToPrevScale
      phoneFrame.endX = phoneFrame.x + phoneFrame.endX *  phoneFrameToPrevScale
      phoneFrame.endY = phoneFrame.y + phoneFrame.endY *  phoneFrameToPrevScale

      phoneFrame.x = (width - phoneFrame.width)/2

      // 绘制文字
      if (this.text == null) this.text = ""
      let text = this.text.split("\\n")
      if (text.length <= 1) {
        text = this.text.split("\n") // 切换真实换行
      }
      ctx2d.beginPath();
      ctx2d.fillStyle = "#FFFFFF"
      ctx2d.imageSmoothingEnabled = true
      ctx2d.imageSmoothingQuality = 'high';

      ctx2d.textAlign = "center" // "left" || "right" || "center"
      let upHeight = 64
      if (text.length === 1) {
        upHeight = 132
      }
      for (let i = 0; i < text.length && i < 2; i++) {
        ctx2d.font = "bolder 76px Arial";
        ctx2d.fillText(text[i], width / 2, 100 * (i + 1) + upHeight, width - phoneFrame.x);
      }
      ctx2d.closePath()



      // 新方案 绘制手机截图
      var screenImg = new Image();
      screenImg.crossOrigin = "Anonymous";
      screenImg.onload = function () {
        // 手机截图保证内容区拉伸占满
        const scale = Math.max((phoneFrame.width) / this.width, (phoneFrame.height) / this.height)
        // console.log("width: " + (phoneFrame.endX - phoneFrame.startX) / this.width + " height: " + this.height + " scale: " + scale);

        phoneFrame.height = phoneFrame.width  * this.height / this.width;

        console.log("height : " + phoneFrame.height)

        // 在临时的 Canvas 上绘制圆角图片和阴影
        // var tempCanvas = document.createElement('canvas');
        // var tempCtx = tempCanvas.getContext('2d');
        // tempCanvas.width = canvas.width;
        // tempCanvas.height = canvas.height;
        //
        // var cornerRadius = 94; // 圆角半径
        // tempCtx.save();
        // tempCtx.beginPath();
        // tempCtx.moveTo(phoneFrame.x + cornerRadius, phoneFrame.y);
        // tempCtx.arcTo(phoneFrame.x + phoneFrame.width, phoneFrame.y, phoneFrame.x + phoneFrame.width, phoneFrame.y + phoneFrame.height, cornerRadius);
        // tempCtx.arcTo(phoneFrame.x + phoneFrame.width, phoneFrame.y + phoneFrame.height, phoneFrame.x, phoneFrame.y + phoneFrame.height, cornerRadius);
        // tempCtx.arcTo(phoneFrame.x, phoneFrame.y + phoneFrame.height, phoneFrame.x, phoneFrame.y, cornerRadius);
        // tempCtx.arcTo(phoneFrame.x, phoneFrame.y, phoneFrame.x + phoneFrame.width, phoneFrame.y, cornerRadius);
        // tempCtx.closePath();
        // tempCtx.clip();
        //
        // tempCtx.drawImage(this, phoneFrame.x, phoneFrame.y, phoneFrame.width, phoneFrame.height);
        // tempCtx.restore()
        //
        // ctx2d.shadowBlur = 80;
        // ctx2d.shadowColor = "rgba(0, 0, 0, 0.3)";
        // // 将临时的 Canvas 绘制到原始 Canvas 上
        // ctx2d.drawImage(tempCanvas, 0, 0);
        //
        // var gradient = ctx2d.createLinearGradient(0, 0, 0, 40);
        // gradient.addColorStop(0, "#121212");
        // gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
        //
        // ctx2d.fillStyle = gradient;
        // ctx2d.fillRect(0, canvas.height - 40, canvas.width, 40);

        let x = phoneFrame.x; // 矩形框的x位置
        let y = phoneFrame.y; // 矩形框的y位置
        let width = phoneFrame.width; // 矩形框的宽度
        let height = phoneFrame.height; // 矩形框的高度
        let innerRadius = 40; // 内角半径
        let outerRadius = 64; // 外角半径
        let frameWidth = 28;

        ctx2d.beginPath();
        ctx2d.roundRect(x, y, width, height, outerRadius)

        ctx2d.closePath();

        ctx2d.lineWidth = 1;
        ctx2d.fillStyle = "black";
        ctx2d.fill();

        ctx2d.save();
        ctx2d.beginPath();
        ctx2d.roundRect(x + frameWidth, y + frameWidth, width - 2*frameWidth, height- 2* frameWidth, innerRadius)
        ctx2d.closePath();
        ctx2d.clip();
        ctx2d.drawImage(this, x + frameWidth ,y + frameWidth, width - 2*frameWidth, height- 2* frameWidth);
        ctx2d.restore()



      }

      if (this.screenBlobImg != null) {
        const reader = new FileReader();
        // 设置读取完成时的回调函数
        reader.onload = function (event) {
          // 将读取的数据设置为 Image 对象的 src
          screenImg.src = event.target.result;
        };
        reader.readAsDataURL(this.screenBlobImg);
      } else {
        screenImg.src = this.screenUrl;
      }




    },
    exportImages() {
      const canvas = this.$refs.screenCanvas;
      var dataURL = canvas.toDataURL("image/png", 0.9); // 将canvas转换为data URL
      var canvasBlob = this.dataURLtoBlob(dataURL)

      let fileOfBlob = new File([canvasBlob], new Date().getTime() + '.jpg')
      return fileOfBlob
    },
    dataURLtoBlob(dataurl) {
      var arr = dataurl.split(',')
      //注意base64的最后面中括号和引号是不转译的
      var _arr = arr[1].substring(0, arr[1].length - 2)
      var mime = arr[0].match(/:(.*?);/)[1],
          bstr = atob(_arr),
          n = bstr.length,
          u8arr = new Uint8Array(n)
      while (n--) {
        u8arr[n] = bstr.charCodeAt(n)
      }
      return new Blob([u8arr], {
        type: mime
      })
    }
  },
  mounted() {
    this.refreshCanvas()
  },
  watch: {
    canvasWidth(newValue, oldValue) {
      console.log('canvasWidth 变化:', newValue);
      this.refreshCanvas(this.text)
    },
    canvasHeight(newValue, oldValue) {
      console.log('canvasHeight 变化:', newValue);
      // 处理 canvasHeight 变化的逻辑
      this.refreshCanvas(this.text)
    },
    text(newValue, oldValue) {
      console.log('text 变化:', newValue);
      // 处理 text 变化的逻辑
      this.refreshCanvas(this.text)
    },
    backgroundColor(newValue, oldValue) {
      console.log('backgroundColor 变化:', newValue);
      // 处理 backgroundColor 变化的逻辑
      this.refreshCanvas(this.text)
    },
    frameImgUrl(newValue, oldValue) {
      console.log('frameImgUrl 变化:', newValue);
      // 处理 frameImgUrl 变化的逻辑
      this.refreshCanvas(this.text)
    },
    screenBlobImg(newValue, oldValue) {
      console.log('screenBlobImg 变化:', newValue);
      this.refreshCanvas(this.text)
      // 处理 screenBlobImg 变化的逻辑
    },
    textAlign(newValue, oldValue) {
      console.log('screenBlobImg 变化:', newValue);
      this.refreshCanvas(this.text)
      // 处理 screenBlobImg 变化的逻辑
    },
  }
}
</script>
